package com.tripmateai.mapper; import com.tripmateai.dto.response.budget.BudgetResponse; import com.tripmateai.entity.Budget; public final class BudgetMapper {private BudgetMapper(){} public static BudgetResponse toResponse(Budget b){return b==null?null:new BudgetResponse(b.getId(),b.getTrip().getId(),b.getTotalBudget(),b.getAllocatedAmount(),b.getSpentAmount(),b.getCurrency());}}
